(()=>{document.addEventListener("DOMContentLoaded",function(){let t=document.getElementById("search-input"),e=document.getElementById("search-dropdown");if(!t||!e)return;let d;t.addEventListener("input",function(){clearTimeout(d);let i=t.value;if(i.length<2){e.classList.add("hidden");return}d=setTimeout(function(){fetch("/products/suggest?q="+encodeURIComponent(i)).then(function(n){return n.text()}).then(function(n){e.innerHTML=n,e.classList.toggle("hidden",!n.trim())})},300)}),t.addEventListener("blur",function(){setTimeout(function(){e.classList.add("hidden")},150)}),t.addEventListener("focus",function(){t.value.length>=2&&e.classList.remove("hidden")})});})();
